$env:GCM_INTERACTIVE="never"
$cred = "protocol=https`nhost=github.com`n`n" | & git credential fill 2>$null
$token = ($cred | Where-Object { $_ -like 'password=*' } | Select-Object -First 1).Substring(9)
if (-not $token) { throw "no token" }
$headers = @{ Authorization = "Bearer $token"; "User-Agent" = "opencode"; Accept = "application/vnd.github+json"; "X-GitHub-Api-Version" = "2022-11-28" }
$body = Get-Content -Raw "C:\Users\ALQasem\AppData\Local\Temp\opencode\pr-body.md"
$payload = @{ title = "feat: SQL Server migration, subscription pro-rated refunds, admin payments & revenue split"; head = "fix/push-main-block"; base = "main"; body = $body } | ConvertTo-Json -Depth 5
try {
  $resp = Invoke-RestMethod -Uri "https://api.github.com/repos/MohamedSaber2004/ClinicHub/pulls" -Method Post -Headers $headers -Body ([System.Text.Encoding]::UTF8.GetBytes($payload)) -ContentType "application/json; charset=utf-8"
  "PR #" + $resp.number + " -> " + $resp.html_url
  "state: " + $resp.state + " | draft: " + $resp.draft + " | mergeable_state pending"
} catch {
  $r = $_.Exception.Response
  if ($r) { $sr = New-Object System.IO.StreamReader($r.GetResponseStream()); "HTTP " + [int]$r.StatusCode + ": " + $sr.ReadToEnd() } else { $_.Exception.Message }
}

$env:GCM_INTERACTIVE="never"
$cred = "protocol=https`nhost=github.com`n`n" | & git credential fill 2>$null
$token = ($cred | Where-Object { $_ -like 'password=*' } | Select-Object -First 1).Substring(9)
$headers = @{ Authorization = "Bearer $token"; "User-Agent" = "opencode"; Accept = "application/vnd.github+json" }
$payload = @{ title = "probe"; head = "fix/push-main-block"; base = "main" } | ConvertTo-Json
try {
  $resp = Invoke-RestMethod -Uri "https://api.github.com/repos/MohamedSaber2004/ClinicHub/pulls" -Method Post -Headers $headers -Body $payload -ContentType "application/json"
  "OK #" + $resp.number
} catch {
  $ex = $_.Exception
  "MSG: " + $ex.Message
  $r = $ex.Response
  if ($r -ne $null) {
    "STATUS: " + [int]$r.StatusCode
    $stream = $r.GetResponseStream()
    if ($stream -ne $null) { $reader = New-Object System.IO.StreamReader($stream); "BODY: " + $reader.ReadToEnd() } else { "no stream" }
  }
}

$env:GCM_INTERACTIVE="never"
$cred = "protocol=https`nhost=github.com`n`n" | & git credential fill 2>$null
$token = ($cred | Where-Object { $_ -like 'password=*' } | Select-Object -First 1).Substring(9)
$headers = @{ Authorization = "Bearer $token"; "User-Agent" = "opencode"; Accept = "application/vnd.github+json" }
$body = [System.IO.File]::ReadAllText("C:\Users\ALQasem\AppData\Local\Temp\opencode\pr-body.md", [System.Text.Encoding]::UTF8)
$payload = @{ title = "feat: SQL Server migration, subscription pro-rated refunds, admin payments & revenue split"; body = $body } | ConvertTo-Json -Depth 5
$bytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
"payload bytes: " + $bytes.Length
try {
  $resp = Invoke-RestMethod -Uri "https://api.github.com/repos/MohamedSaber2004/ClinicHub/pulls/3" -Method Patch -Headers $headers -Body $bytes -ContentType "application/json; charset=utf-8"
  "UPDATED #" + $resp.number + " | " + $resp.title
  "url: " + $resp.html_url
  "body chars: " + $resp.body.Length
} catch {
  $ex = $_.Exception
  "MSG: " + $ex.Message
  $r = $ex.Response
  if ($r -ne $null) { "STATUS: " + [int]$r.StatusCode; $s = $r.GetResponseStream(); if ($s) { "BODY: " + (New-Object System.IO.StreamReader($s)).ReadToEnd() } }
}

