```js
(() => {
  const d = document.querySelector('iframe').contentDocument;
  const w = d.querySelector('.register-form-card');
  const lbl = w.querySelector('.form-label');
  const cs = d.defaultView.getComputedStyle(lbl);
  return JSON.stringify({ ta: cs.textAlign, dir: cs.direction, fs: cs.fontSize, groupMb: d.defaultView.getComputedStyle(w.querySelector('.form-group')).marginBottom });
})()
