  unicode-bidi: isolate;
  display: inline-block;
  font-variant-numeric: tabular-nums;
}

/* Map pickers share one height so the same control looks the same everywhere */
.register-map-container,
.settings-map {
  height: var(--map-picker-height, 240px);
  min-height: 200px;
}

/* Search row: room to breathe, and a full-width button once it can no longer sit inline */
.map-search-row,
.register-map-search-row {
  gap: var(--space-2);
  flex-wrap: wrap;
}

.map-search-row .form-input,
.register-map-search-row .form-input { min-height: 44px; }

.map-search-btn,
.register-map-search-btn { min-height: 44px; padding-inline: var(--space-4); }

@media (max-width: 576px) {
