/* ============================================================
   Inputs & map pickers — responsive + accessibility pass
   - one map-picker height for every map (register / settings / admin)
   - search rows get real spacing and a full-width button on phones
   - coordinates stay LTR so the pair is never reordered by bidi
   - 16px controls on small screens (stops iOS focus zoom)
   - registration form density restored to the shared rhythm
   ============================================================ */

/* Coordinates are data, not prose: isolate them from the RTL flow */
.register-coords-display,
.settings-coords-display {
  direction: ltr;
  unicode-bidi: isolate;
  display: inline-block;
  font-variant-numeric: tabular-nums;
}

/* One map height everywhere a pin is placed on a map */
.register-map-container,
.settings-map {
  height: var(--map-picker-height, 240px);
}

.map-search-row,
.register-map-search-row {
  gap: var(--space-2);
  flex-wrap: wrap;
}

.map-search-row .form-input,
.register-map-search-row .form-input {
  min-height: 44px;
}

.map-search-btn,
.register-map-search-btn {
  min-height: 44px;
  padding-inline: var(--space-4);
}

/* Google Places suggestions sit on <body>; keep them above dashboard overlays */
.pac-container {
  z-index: 2000;
}

/* Registration fields were stacked 5px apart, alone among all forms */
.register-form-card .form-group {
  margin-bottom: var(--space-4);
}

.register-form-card .row {
  --bs-gutter-y: var(--space-3);
}

@media (max-width: 991px) {
  /* iOS zooms the page when a focused control is under 16px */
  .form-input,
  .form-select,
  .form-textarea,
  .form-control,
  .form-input-sm,
  .auth-form-control {
    font-size: 16px;
  }
}

@media (max-width: 576px) {
  :root {
    --map-picker-height: 280px;
  }

  .map-search-row,
  .register-map-search-row {
    gap: var(--space-1);
    margin-bottom: var(--space-2);
  }

  /* Below this width the field and its button can no longer share a line */
  .map-search-row .map-search-btn,
  .register-map-search-row .register-map-search-btn {
    flex: 1 1 100%;
  }
}
