const fs = require('fs');
const path = require('path');

const root = 'E:/ClinicHub-Frontend/ClinicHub/Views';
const files = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith('.cshtml')) files.push(p);
  }
})(root);

const report = [];
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const lines = src.split(/\r?\n/);
  const labelFor = new Set([...src.matchAll(/<label[^>]*\bfor="([^"]+)"/g)].map(m => m[1]));
  const ids = new Set([...src.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]));

  lines.forEach((line, i) => {
    const m = line.match(/<input\b([^>]*)>/);
    if (!m) return;
    const attrs = m[1];
    if (/\btype="(hidden|submit|button|reset|checkbox|radio|file)"/.test(attrs)) return;
    const idm = attrs.match(/\bid="([^"]+)"/);
    const hasAria = /aria-label(?:ledby)?=/.test(attrs);
    if (!idm) {
      report.push({ f, line: i + 1, issue: 'input without id (cannot be labelled)', text: line.trim().slice(0, 120) });
      return;
    }
    const id = idm[1];
    if (!labelFor.has(id) && !hasAria) {
      report.push({ f, line: i + 1, issue: `no <label for="${id}">`, text: line.trim().slice(0, 120) });
    }
  });

  lines.forEach((line, i) => {
    const m = line.match(/<textarea\b([^>]*)>/);
    if (!m) return;
    const idm = m[1].match(/\bid="([^"]+)"/);
    if (!idm) report.push({ f, line: i + 1, issue: 'textarea without id', text: line.trim().slice(0, 120) });
    else if (!labelFor.has(idm[1]) && !/aria-label/.test(m[1])) {
      report.push({ f, line: i + 1, issue: `textarea no <label for="${idm[1]}">`, text: line.trim().slice(0, 120) });
    }
    if (/class="form-input"/.test(m[1])) report.push({ f, line: i + 1, issue: 'textarea uses form-input instead of form-textarea', text: line.trim().slice(0, 120) });
  });
}

const byFile = {};
for (const r of report) (byFile[r.f] = byFile[r.f] || []).push(r);
const rel = p => p.replace(/\\/g, '/').replace(root, 'Views');
for (const f of Object.keys(byFile)) {
  console.log('\n### ' + rel(f) + ' (' + byFile[f].length + ')');
  for (const r of byFile[f]) console.log('  ' + r.line + ': ' + r.issue);
}
console.log('\nTOTAL: ' + report.length + ' across ' + Object.keys(byFile).length + ' files');

const fs = require('fs');
const path = require('path');

const root = 'E:/ClinicHub-Frontend/ClinicHub/Views';
const files = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith('.cshtml')) files.push(p);
  }
})(root);

const changes = [];

for (const file of files) {
  const raw = fs.readFileSync(file, 'utf8');
  const eol = raw.includes('\r\n') ? '\r\n' : '\n';
  const lines = raw.split(/\r?\n/);
  let touched = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // A) label without a for= that is followed by a single control with an id
    const lm = line.match(/<label\b([^>]*)>/);
    if (lm && /\bclass="[^"]*\bform-label\b[^"]*"/.test(lm[1]) && !/\bfor=/.test(lm[1])) {
      let controlId = null;
      let controlLine = -1;
      for (let j = i + 1; j < Math.min(i + 5, lines.length); j++) {
        const next = lines[j];
        if (/<label\b/.test(next)) break;
        const cm = next.match(/<(input|select|textarea)\b([^>]*)>/);
        if (cm) {
          const idm = cm[2].match(/\bid="([^"]+)"/);
          if (idm) { controlId = idm[1]; controlLine = j; }
          break;
        }
      }
      if (controlId) {
        lines[i] = line.replace(/(<label\b[^>]*?)(\s*>)/, `$1 for="${controlId}"$2`);
        touched = true;
        changes.push(`${path.relative(root, file).replace(/\\/g, '/')}:${i + 1}  label -> for="${controlId}"`);
      }
    }

    // B) textarea styled as a single-line input
    if (/<textarea\b/.test(lines[i]) && /\bclass="form-input"/.test(lines[i])) {
      lines[i] = lines[i].replace(/\bclass="form-input"/, 'class="form-input form-textarea"');
      touched = true;
      changes.push(`${path.relative(root, file).replace(/\\/g, '/')}:${i + 1}  textarea -> form-input form-textarea`);
    }
  }

  if (touched) fs.writeFileSync(file, lines.join(eol), 'utf8');
}

console.log(changes.join('\n'));
console.log('\n' + changes.length + ' edits');

const fs = require('fs');
const path = require('path');

const root = 'E:/ClinicHub-Frontend/ClinicHub/Views';
const files = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith('.cshtml')) files.push(p);
  }
})(root);

const done = [], skipped = [];

for (const file of files) {
  const raw = fs.readFileSync(file, 'utf8');
  const eol = raw.includes('\r\n') ? '\r\n' : '\n';
  const lines = raw.split(/\r?\n/);
  const idsInFile = new Set([...raw.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]));
  let touched = false;

  for (let i = 0; i < lines.length; i++) {
    const lm = lines[i].match(/<label\b([^>]*)>/);
    if (!lm || !/\bclass="[^"]*\bform-label\b[^"]*"/.test(lm[1]) || /\bfor=/.test(lm[1])) continue;

    let ci = -1, cm = null;
    for (let j = i + 1; j < Math.min(i + 6, lines.length); j++) {
      if (/<label\b/.test(lines[j])) break;
      const m = lines[j].match(/<(input|select|textarea)\b([^>]*)>/);
      if (m) { ci = j; cm = m; break; }
    }
    if (!cm) continue;

    const attrs = cm[2];
    if (/\btype="(hidden|submit|button|reset)"/.test(attrs)) continue;
    if (/\bid="/.test(attrs)) continue; // handled by the first pass

    const nameM = attrs.match(/\bname="([^"]+)"/);
    if (!nameM) { skipped.push(`${path.relative(root, file)}:${ci + 1}  no name to derive an id from`); continue; }

    let id = nameM[1].replace(/[^A-Za-z0-9_\-]/g, '_');
    if (idsInFile.has(id)) { skipped.push(`${path.relative(root, file)}:${ci + 1}  id "${id}" already used`); continue; }

    const newAttrs = attrs.replace(/^(\s*)/, `$1id="${id}" `);
    const tag = cm[1];
    lines[ci] = lines[ci].replace(new RegExp(`<${tag}\\b[^>]*>`), `<${tag}${newAttrs}>`);
    lines[i] = lines[i].replace(/(<label\b[^>]*?)(\s*>)/, `$1 for="${id}"$2`);
    idsInFile.add(id);
    touched = true;
    done.push(`${path.relative(root, file).replace(/\\/g, '/')}:${i + 1}  id+for "${id}"`);
  }

  if (touched) fs.writeFileSync(file, lines.join(eol), 'utf8');
}

console.log('--- applied (' + done.length + ') ---');
console.log(done.join('\n'));
console.log('\n--- skipped (' + skipped.length + ') ---');
console.log(skipped.join('\n'));

