const fs = require('fs');
const path = require('path');

const root = 'E:/ClinicHub-Frontend/ClinicHub/Views';
const R = (p) => path.join(root, p);

const edits = [
  // [file, needle (ASCII tag prefix, unique), accessible name, replaceAll?]
  ['Admin/Ads.cshtml', '<input type="text" id="adsLocalSearch" class="form-input ads-global-input"', 'بحث في الإعلانات'],
  ['Admin/AdsSubscriptions.cshtml', '<input type="text" id="adsGlobalSearch" class="form-input ads-global-input"', 'بحث في اشتراكات الإعلانات'],
  ['Admin/AdsSubscriptions.cshtml', '<input type="text" class="form-input form-input-sm ads-table-filter" data-target="plans"', 'بحث في الباقات'],
  ['Admin/AdsSubscriptions.cshtml', '<input type="text" class="form-input form-input-sm ads-table-filter" data-target="packages"', 'بحث في حزم الإعلانات'],
  ['Admin/AdsSubscriptions.cshtml', '<input type="text" class="form-input form-input-sm ads-table-filter" data-target="clinics"', 'بحث عن عيادة'],
  ['Admin/AdsSubscriptions.cshtml', '<input type="text" class="form-input form-input-sm ads-table-filter" data-target="subs"', 'بحث عن مشترك'],
  ['Admin/Doctors.cshtml', '<input type="text" name="searchTerm" class="form-input"', 'بحث عن طبيب'],
  ['Admin/Payments.cshtml', '<input type="text" name="summarySearch"', 'بحث في المدفوعات'],
  ['Admin/Payments.cshtml', '<input type="text" name="searchTerm" class="form-input"', 'بحث في المدفوعات'],
  ['Admin/Payments.cshtml', '<input type="date" name="fromDate"', 'من تاريخ'],
  ['Admin/Payments.cshtml', '<input type="date" name="toDate"', 'إلى تاريخ'],
  ['Admin/Specializations.cshtml', '<input type="text" id="filterSearch"', 'بحث في التخصصات'],
  ['Admin/Users/Index.cshtml', '<input type="text" id="filterSearch"', 'بحث في المستخدمين'],
  ['Clinic/ClinicAvailability.cshtml', '<input type="text" class="form-input" id="workingHoursSummaryInput"', 'ملخص أوقات العمل'],
  ['Clinic/DoctorAppointments.cshtml', '<input type="date" name="startDate"', 'من تاريخ'],
  ['Clinic/DoctorAppointments.cshtml', '<input type="date" name="endDate"', 'إلى تاريخ'],
  ['Clinic/DoctorAppointments.cshtml', '<input type="text" name="searchTerm"', 'بحث في المواعيد'],
  ['Clinic/DoctorPatients.cshtml', '<input type="text" name="searchTerm"', 'بحث عن مريض'],
  ['Clinic/MedicalRecords.cshtml', '<input type="text" name="searchTerm"', 'بحث في السجلات الطبية'],
  ['Clinic/Marketing.cshtml', '<input type="text" id="marketingAdsSearch"', 'بحث في الإعلانات'],
  ['Clinic/PatientPortal.cshtml', '<input type="text" class="form-input form-input-sm flex-grow-1"', 'اكتب رسالتك', true],
  ['Doctor/Appointments.cshtml', '<input type="date" name="startDate"', 'من تاريخ'],
  ['Doctor/Appointments.cshtml', '<input type="date" name="endDate"', 'إلى تاريخ'],
  ['Doctor/Appointments.cshtml', '<input type="text" name="searchTerm"', 'بحث في المواعيد'],
  ['Doctor/Patients.cshtml', '<input type="text" name="searchTerm"', 'بحث عن مريض'],
  ['Home/Subscriptions.cshtml', '<input type="text" id="planSearch"', 'بحث في الباقات'],
  ['Staff/Appointments.cshtml', '<input type="date" name="date"', 'تاريخ الموعد'],
  ['Staff/Appointments.cshtml', '<input type="text" name="searchTerm"', 'بحث في المواعيد']
];

const log = [];
const missed = [];
const byFile = new Map();
for (const e of edits) {
  if (!byFile.has(e[0])) byFile.set(e[0], []);
  byFile.get(e[0]).push(e);
}

for (const [rel, list] of byFile) {
  const file = R(rel);
  let raw = fs.readFileSync(file, 'utf8');
  let touched = false;

  for (const [, needle, label, all] of list) {
    const hits = raw.split(needle).length - 1;
    if (hits === 0) { missed.push(`${rel}  needle not found: ${needle}`); continue; }
    if (hits > 1 && !all) { missed.push(`${rel}  needle matched ${hits}x: ${needle}`); continue; }
    const replacement = `${needle} aria-label="${label}"`;
    // do not double-apply
    const already = raw.includes(`${needle} aria-label="${label}"`);
    if (already) { missed.push(`${rel}  already labelled: ${needle}`); continue; }
    raw = all ? raw.split(needle).join(replacement) : raw.replace(needle, replacement);
    touched = true;
    log.push(`${rel}  aria-label="${label}"  (${hits}x)`);
  }

  if (touched) fs.writeFileSync(file, raw, 'utf8');
}

console.log('--- applied (' + log.length + ') ---');
console.log(log.join('\n'));
if (missed.length) {
  console.log('\n--- skipped (' + missed.length + ') ---');
  console.log(missed.join('\n'));
}

const fs = require('fs');

const file = 'E:/ClinicHub-Frontend/ClinicHub/Views/Admin/Clinics.cshtml';
let raw = fs.readFileSync(file, 'utf8');
const log = [];

const pairs = [
  ['الاسم', 'filterName'],
  ['البريد الإلكتروني', 'filterEmail'],
  ['رقم الهاتف', 'filterPhone'],
  ['من تاريخ', 'filterCreatedFrom'],
  ['إلى تاريخ', 'filterCreatedTo'],
  ['ترتيب حسب', 'filterSortBy']
];

for (const [text, id] of pairs) {
  const needle = `<label class="filter-label">${text}</label>`;
  if (!raw.includes(needle)) { log.push(`MISS  ${text}`); continue; }
  raw = raw.replace(needle, `<label class="filter-label" for="${id}">${text}</label>`);
  log.push(`for="${id}"  ${text}`);
}

// sort-direction is a radio group, not a single control
const groupNeedle = '<label class="filter-label">اتجاه الترتيب</label>\n                    <div class="sort-direction-group">';
const groupNeedleCrlf = '<label class="filter-label">اتجاه الترتيب</label>\r\n                    <div class="sort-direction-group">';
if (raw.includes(groupNeedleCrlf)) {
  raw = raw.replace(groupNeedleCrlf, '<label class="filter-label" id="sortDirLabel">اتجاه الترتيب</label>\r\n                    <div class="sort-direction-group" role="group" aria-labelledby="sortDirLabel">');
  log.push('group aria-labelledby="sortDirLabel"  اتجاه الترتيب');
} else if (raw.includes(groupNeedle)) {
  raw = raw.replace(groupNeedle, '<label class="filter-label" id="sortDirLabel">اتجاه الترتيب</label>\n                    <div class="sort-direction-group" role="group" aria-labelledby="sortDirLabel">');
  log.push('group aria-labelledby="sortDirLabel"  اتجاه الترتيب');
} else {
  log.push('MISS  اتجاه الترتيب (group)');
}

fs.writeFileSync(file, raw, 'utf8');
console.log(log.join('\n'));

