157:             function buildDaysPayload() {
158:                 var days = [];
159:                 var valid = true;
160:                 var filled = 0;
161:                 $('.availability-row').each(function () {
162:                     var day = $(this).find('.availability-day').val();
163:                     var from = readTime($(this), 'from');
164:                     var to = readTime($(this), 'to');
165:                     if (!day) { valid = false; return false; }
166:                     if ((from && !to) || (!from && to)) { valid = false; return false; }
167:                     if (!from || !to) return true;
168: 
169:                     if (to <= from) { valid = false; return false; }
170: 
171:                     filled++;
172:                     var item = {
