174:                         startTime: from + ':00',
175:                         endTime: to + ':00',
176:                         slotDurationMinutes: 30
177:                     };
178:                     var id = $(this).attr('data-id');
179:                     if (id) item.id = id;
180:                     days.push(item);
181:                 });
182:                 return { valid: valid, filled: filled, days: days };
183:             }
