const tabID = "tab_c6a58ca9-0e12-4640-b929-5fa284082c58";
const script = `(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let f = document.querySelector('iframe');
  for (let i = 0; i < 40; i++) {
    if (f && f.contentDocument && f.contentDocument.querySelector('.availability-row')) break;
    await sleep(100);
  }
  await sleep(350);
  const d = f.contentDocument, w = f.contentWindow;
  const cs = el => w.getComputedStyle(el);
  const R = el => el.getBoundingClientRect();
  const cvs = d.createElement('canvas').getContext('2d');
  const clamp = (sel) => {
    const c = cs(sel);
    cvs.font = c.fontWeight + ' ' + c.fontSize + ' ' + c.fontFamily;
    const txt = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].text : '';
    const avail = sel.clientWidth - parseFloat(c.paddingLeft) - parseFloat(c.paddingRight);
    return { txt, textW: Math.round(cvs.measureText(txt).width), avail: Math.round(avail) };
  };
  const row = d.querySelector('.availability-row');
  const kids = [...row.children].filter(e => cs(e).display !== 'none');
  return JSON.stringify({
    rowH: Math.round(R(row).height),
    font: cs(row.querySelector('.availability-from-period')).fontSize,
    line1: [...row.children].filter(e => Math.round(R(e).top) === Math.round(R(kids[0]).top)).map(e => e.className.split(' ')[0] + '@' + Math.round(R(e).width)),
    clips: [...row.querySelectorAll('select')].map(s => {
      const g = clamp(s);
      return { cls: s.className.split(' ')[0], w: Math.round(R(s).width), txt: g.txt, textW: g.textW, avail: g.avail,
               clipped: g.textW > g.avail };
    }),
    overflowX: d.documentElement.scrollWidth > d.documentElement.clientWidth
  }, null, 2);
})()`;
const out = {};
for (const w of [393, 576, 768, 1280]) {
  await tools.browser.navigate({ tabID, url: "http://127.0.0.1:8848/e" + w + ".html?x=" + Math.random() });
  const r = await tools.browser.evaluate({ tabID, script });
  try { out[w] = JSON.parse(r.value); } catch (e) { out[w] = r.value; }
}
return JSON.stringify(out, null, 2);

