input.newString:
/* Widths are preference, not a hard floor: in a narrow content column on a
   desktop the row shrinks down to the min-widths (which are just big enough
   for the padding + the widest option text) instead of spilling sideways. */
.availability-row .availability-day {
  width: 110px;
  min-width: 84px;
  flex-shrink: 1;
}

.availability-row .availability-from-hour,
.availability-row .availability-to-hour {
  width: 74px;
  min-width: 60px;
  flex-shrink: 1;
}

.availability-row .availability-from-minute,
.availability-row .availability-to-minute {
  width: 74px;
  min-width: 60px;
  flex-shrink: 1;
}

.availability-row .availability-from-period,
.availability-row .availability-to-period {
  width: 95px;
  min-width: 80px;
  flex-shrink: 1;
}

