const script = (maxW) => `(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let f = document.querySelector('iframe');
  for (let i = 0; i < 50; i++) {
    if (f && f.contentDocument && f.contentDocument.querySelector('.availability-row')) break;
    await sleep(100);
  }
  await sleep(450);
  const d = f.contentDocument, w = f.contentWindow;
  const card = d.querySelector('.detail-card');
  if (${maxW}) { card.style.maxWidth = '${maxW}px'; card.style.margin = '0 auto'; }
  await sleep(150);
  const cs = el => w.getComputedStyle(el);
  const R = el => el.getBoundingClientRect();
  const cvs = d.createElement('canvas').getContext('2d');
  const row = d.querySelector('.availability-row');
  const top0 = Math.round(R(row.children[0]).top);
  const lines = {};
  [...row.children].filter(e => cs(e).display !== 'none').forEach(e => {
    const t = Math.round(R(e).top);
    lines[t] = (lines[t] || 0) + 1;
  });
  const meas = [...row.querySelectorAll('select')].map(s => {
    const c = cs(s);
    cvs.font = c.fontWeight + ' ' + c.fontSize + ' ' + c.fontFamily;
    const widest = Math.max(...[...s.options].map(o => cvs.measureText(o.text).width));
    const avail = s.clientWidth - parseFloat(c.paddingLeft) - parseFloat(c.paddingRight);
    return { cls: s.className.split(' ')[0].replace('availability-', ''), w: Math.round(R(s).width),
             need: Math.round(widest + parseFloat(c.paddingLeft) + parseFloat(c.paddingRight)),
             clipped: widest > avail + 0.5 };
  });
  return JSON.stringify({
    container: Math.round(R(row).width),
    rowH: Math.round(R(row).height),
    lineCount: Object.keys(lines).length,
    clipped: meas.filter(m => m.clipped).map(m => m.cls),
    widths: meas.map(m => m.cls + ':' + m.w + '/' + m.need),
    scrollOverflow: row.scrollWidth > row.clientWidth + 1,
    docOverflow: d.documentElement.scrollWidth > d.documentElement.clientWidth
  });
})()`;
const out = {};
for (const [vw, cw] of [[1280, 0], [1280, 700], [1280, 620], [1024, 700], [393, 0]]) {
