const tabID = "tab_c6a58ca9-0e12-4640-b929-5fa284082c58";
const script = `(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let f = null;
  for (let i = 0; i < 60; i++) {
    f = document.querySelector('iframe');
    if (f && f.contentDocument && f.contentDocument.querySelectorAll('.availability-row').length >= 2) break;
    await sleep(100);
  }
  await sleep(500);
  const d = f.contentDocument, w = f.contentWindow;
  const cs = el => w.getComputedStyle(el);
  const R = el => el.getBoundingClientRect();
  const cvs = d.createElement('canvas').getContext('2d');
  const rows = [...d.querySelectorAll('.availability-row')];
  return JSON.stringify({
    rows: rows.map((row, i) => ({
      i,
      h: Math.round(R(row).height),
      pad: cs(row).padding,
      gap: cs(row).gap,
      day: { w: Math.round(R(row.querySelector('.availability-day')).width), font: cs(row.querySelector('.availability-day')).fontSize },
      hour: { w: Math.round(R(row.querySelector('.availability-from-hour')).width), font: cs(row.querySelector('.availability-from-hour')).fontSize, padL: cs(row.querySelector('.availability-from-hour')).paddingLeft },
      remove: { w: Math.round(R(row.querySelector('.availability-remove-btn')).width), h: Math.round(R(row.querySelector('.availability-remove-btn')).height) },
      sep: cs(row.querySelector('.availability-sep')).display,
      clipped: [...row.querySelectorAll('select')].filter(s => {
        const c = cs(s);
        cvs.font = c.fontWeight + ' ' + c.fontSize + ' ' + c.fontFamily;
        const widest = Math.max(...[...s.options].map(o => cvs.measureText(o.text).width));
        return widest > s.clientWidth - parseFloat(c.paddingLeft) - parseFloat(c.paddingRight) + 0.5;
      }).length,
      overflow: row.scrollWidth > row.clientWidth + 1
    })),
    docOverflow: d.documentElement.scrollWidth > d.documentElement.clientWidth
  }, null, 2);
})()`;
const out = {};
for (const w of [393, 1280]) {
  await tools.browser.navigate({ tabID, url: "http://127.0.0.1:8848/e" + w + ".html?y=" + Math.random() });
  const r = await tools.browser.evaluate({ tabID, script });
  try { out[w] = JSON.parse(r.value); } catch (e) { out[w] = r.value; }
}
return JSON.stringify(out, null, 2);

