const tabID = "tab_9b42c1bc-a2b7-45c5-b3f8-5c31d291d732";
const script = `(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(3500);
  const f = document.querySelector('iframe');
  const d = f.contentDocument;
  const w = f.contentWindow;
  const cs = el => w.getComputedStyle(el);
  const R = el => el.getBoundingClientRect();
  const ms0 = d.querySelectorAll('.timeline-marker');
  const markers = [];
  for (let i = 0; i < ms0.length; i++) {
    const m = ms0[i];
    const c = cs(m);
    const mR = m.getBoundingClientRect();
    markers.push({ cls: m.className, w: Math.round(mR.width), h: Math.round(mR.height), bg: c.backgroundColor, top: Math.round(mR.top) });
  }
  const first = d.querySelector('.timeline-item');
  const content = d.querySelector('.timeline-content');
  const ccs = cs(content);
  const cR = content.getBoundingClientRect();
  const marker = first.querySelector('.timeline-marker');
  const mR = marker.getBoundingClientRect();
  const timeline = d.querySelector('.timeline');
  const tR = timeline.getBoundingClientRect();
  return JSON.stringify({
    markerCount: ms0.length,
    markers: markers,
    contentDisplay: ccs.display,
    contentDir: ccs.flexDirection,
    contentTop: Math.round(cR.top),
    contentH: Math.round(cR.height),
    contentLeft: Math.round(cR.left),
    contentRight: Math.round(cR.right),
    markerBox: { l: Math.round(mR.left), r: Math.round(mR.right), t: Math.round(mR.top), b: Math.round(mR.bottom) },
    timelineW: Math.round(tR.width),
    timelineH: Math.round(tR.height),
    overflowX: d.documentElement.scrollWidth > d.documentElement.clientWidth,
    scrollW: d.documentElement.scrollWidth,
    clientW: d.documentElement.clientWidth
  }, null, 2);
})()`;
const r = await tools.browser.evaluate({ tabID, script });
return r.value;

